SELECT COALESCE(r.d_date_sk,          r.old__d_date_sk)::text          AS id,
       COALESCE(r.d_date_id,          r.old__d_date_id,          '')   AS date_id,
       COALESCE(r.d_date,             r.old__d_date,             '1970-01-01'::date) AS d_date,
       COALESCE(r.d_month_seq,        r.old__d_month_seq,        0)    AS month_seq,
       COALESCE(r.d_week_seq,         r.old__d_week_seq,         0)    AS week_seq,
       COALESCE(r.d_quarter_seq,      r.old__d_quarter_seq,      0)    AS quarter_seq,
       COALESCE(r.d_year,             r.old__d_year,             0)    AS d_year,
       COALESCE(r.d_dow,              r.old__d_dow,              0)    AS dow,
       COALESCE(r.d_moy,              r.old__d_moy,              0)    AS moy,
       COALESCE(r.d_dom,              r.old__d_dom,              0)    AS dom,
       COALESCE(r.d_qoy,              r.old__d_qoy,              0)    AS qoy,
       COALESCE(r.d_fy_year,          r.old__d_fy_year,          0)    AS fy_year,
       COALESCE(r.d_fy_quarter_seq,   r.old__d_fy_quarter_seq,   0)    AS fy_quarter_seq,
       COALESCE(r.d_fy_week_seq,      r.old__d_fy_week_seq,      0)    AS fy_week_seq,
       COALESCE(r.d_day_name,         r.old__d_day_name,         '')   AS day_name,
       COALESCE(r.d_quarter_name,     r.old__d_quarter_name,     '')   AS quarter_name,
       COALESCE(r.d_holiday,          r.old__d_holiday,          'N')  AS holiday,
       COALESCE(r.d_weekend,          r.old__d_weekend,          'N')  AS weekend,
       COALESCE(r.d_following_holiday,r.old__d_following_holiday,'N')  AS following_holiday,
       COALESCE(r.d_first_dom,        r.old__d_first_dom,        0)    AS first_dom,
       COALESCE(r.d_last_dom,         r.old__d_last_dom,         0)    AS last_dom,
       COALESCE(r.d_same_day_ly,      r.old__d_same_day_ly,      0)    AS same_day_ly,
       COALESCE(r.d_same_day_lq,      r.old__d_same_day_lq,      0)    AS same_day_lq,
       COALESCE(r.d_current_day,      r.old__d_current_day,      'N')  AS current_day,
       COALESCE(r.d_current_week,     r.old__d_current_week,     'N')  AS current_week,
       COALESCE(r.d_current_month,    r.old__d_current_month,    'N')  AS current_month,
       COALESCE(r.d_current_quarter,  r.old__d_current_quarter,  'N')  AS current_quarter,
       COALESCE(r.d_current_year,     r.old__d_current_year,     'N')  AS current_year
FROM {{ .rows }}
